// Карусели: сезоны в каталоге, «Связанные» и «Рекомендации AniList» в карточке; стрелки, автопрокрутка, пауза, состояния.
// Запуск: node design/prototype/carousel.test.js [shots]
const {chromium}=require('playwright');const path=require('path');
const IDX='file://'+path.join(__dirname,'index.html');const OUT=path.join(__dirname,'..','screenshots')+'/';const shots=process.argv[2]==='shots';
(async()=>{const b=await chromium.launch();let fails=0;
const V=[['ПК 1440×900',{viewport:{width:1440,height:900}},''],['телефон 390×844',{viewport:{width:390,height:844},isMobile:true,hasTouch:true},'phone-']];
for(const th of (shots?['dark','light']:['dark']))for(const [vn,o,k] of V){const ctx=await b.newContext({...o,colorScheme:th});const p=await ctx.newPage();const errs=[];p.on('pageerror',e=>errs.push(e.message));
 const ev=(f,a)=>p.evaluate(f,a);const mob=!!o.hasTouch;
 const sel=async(id,v)=>{await ev(([id,v])=>{const s=document.querySelector('#'+id);s.value=v;s.dispatchEvent(new Event('change',{bubbles:true}))},[id,v]);await p.waitForTimeout(300)};
 const go=async h=>{await ev(()=>{location.hash='search'});await p.waitForTimeout(120);await ev(h=>{location.hash=h},h);await p.waitForTimeout(400)};
 const shot=async n=>{await ev(()=>document.querySelectorAll('.toast').forEach(t=>t.remove()));if(shots)await p.screenshot({path:OUT+n+'-'+k+th+'.png'})};
 const sl=id=>ev(id=>document.querySelector('#'+id+' .car-track').scrollLeft,id);
 const noHscroll=()=>ev(()=>document.documentElement.scrollWidth<=innerWidth&&document.querySelector('#main').scrollWidth<=document.querySelector('#main').clientWidth);
 const res=[];const T=async(n,f)=>{try{res.push([n,(await f())?'OK':'FAIL'])}catch(e){res.push([n,'FAIL '+e.message.split('\n')[0].slice(0,80)])}};
 await p.goto(IDX+'#catalog');await p.waitForTimeout(600);
 await T('4 блока сезонов, текущий (осень) первым, затем «Весь каталог»',async()=>{await shot('240-catalog-seasons');return (await ev(()=>[...document.querySelectorAll('.car h2')].map(h=>h.textContent).join('|')))==='Аниме осеннего сезона|Аниме летнего сезона|Аниме весеннего сезона|Аниме зимнего сезона'&&await ev(()=>/Весь каталог/.test(document.querySelector('.cat-all').textContent))&&await noHscroll()});
 await T('Заголовок по центру, капсом, акцентная линия сверху',async()=>await ev(()=>{const h=document.querySelector('#car-0 .car-head');const cs=getComputedStyle(h.querySelector('h2'));const be=getComputedStyle(h,'::before');return cs.textTransform==='uppercase'&&getComputedStyle(h).textAlign==='center'&&be.height==='2px'&&be.backgroundColor===getComputedStyle(document.documentElement).getPropertyValue('--accent').trim().replace(/^#(..)(..)(..)$/,(m,a,b,c)=>`rgb(${parseInt(a,16)}, ${parseInt(b,16)}, ${parseInt(c,16)})`)}));
 await T('Постеры с бейджем оценки и подписью',async()=>await ev(()=>{const c=[...document.querySelectorAll('#car-0 .card')];return c.length>=8&&c.filter(x=>x.querySelector('.score')).length>=7&&c.every(x=>x.querySelector('.name'))}));
 if(!mob){
  await T('Стрелки: «назад» скрыта в начале, «вперёд» сдвигает на карточку',async()=>{const d0=await ev(()=>document.querySelector('#car-0 .car-arr.prev').disabled);await ev(()=>{const c=document.querySelector('#car-0');c.dispatchEvent(new MouseEvent('mouseover',{bubbles:true}))});await p.locator('#car-0 .car-arr.next').click();await p.waitForTimeout(700);const s1=await sl('car-0');return d0&&s1>=170&&s1<=190&&await ev(()=>!document.querySelector('#car-0 .car-arr.prev').disabled)});
  await T('Пауза при наведении: «Пауза» в заголовке, не листается',async()=>{await p.locator('#car-0 .car-track').hover();const s0=await sl('car-0');await p.waitForTimeout(5600);await shot('241-catalog-carousel-paused');return (await sl('car-0'))===s0&&await ev(()=>document.querySelector('#car-0').classList.contains('paused')&&getComputedStyle(document.querySelector('#car-0 .car-auto .lbl')).display!=='none')});
  await T('Без наведения и фокуса: сдвиг на одну карточку за ~5 с (фокус внутри держит паузу)',async()=>{await ev(()=>document.activeElement.blur());await p.mouse.move(700,40);await p.waitForTimeout(200);const s0=await sl('car-0');await p.waitForTimeout(5600);const s1=await sl('car-0');return s1-s0>=170&&s1-s0<=190});
 } else {
  await T('Стрелок на телефоне нет (свайп)',async()=>await ev(()=>getComputedStyle(document.querySelector('#car-0 .car-arr.next')).display==='none'));
  await T('Автопрокрутка: сдвиг на одну карточку за ~5 с',async()=>{const s0=await sl('car-0');await p.waitForTimeout(5600);const s1=await sl('car-0');return s1-s0>=120&&s1-s0<=135});
  await T('Пауза при касании, «Пауза» в заголовке',async()=>{await ev(()=>{const t=document.querySelector('#car-0 .car-track');t.dispatchEvent(new TouchEvent('touchstart',{bubbles:true,touches:[]}))});const s0=await sl('car-0');await p.waitForTimeout(5600);await shot('241-catalog-carousel-paused');return (await sl('car-0'))===s0&&await ev(()=>document.querySelector('#car-0').classList.contains('paused'))});
 }
 await T('Кнопка в заголовке останавливает автопрокрутку совсем',async()=>{await go('catalog');await (mob?p.locator('#car-1 .car-auto').tap():p.locator('#car-1 .car-auto').click());await p.waitForTimeout(200);return await ev(()=>document.querySelector('#car-1').classList.contains('stopped')&&!document.querySelector('#car-1 .car-auto'))});
 await T('Демо «Автопрокрутка: выкл» — ни одна карусель не листается сама',async()=>{await sel('demoAuto','off');const ok=await ev(()=>!document.querySelector('.car.auto')&&!document.querySelector('.car-auto'));await sel('demoAuto','on');return ok});
 await T('Настройка «Автопрокрутка каруселей»',async()=>{await go('settings');const has=await ev(()=>!!document.querySelector('#setAuto'));await ev(()=>document.querySelector('#setAuto').click());const off=await ev(()=>document.querySelector('#demoAuto').value==='off');await ev(()=>document.querySelector('#setAuto').click());return has&&off&&await ev(()=>document.querySelector('#demoAuto').value==='on')});
 await go('catalog');
 await T('Загрузка: скелетоны',async()=>{await sel('demoCar','loading');await shot('242-catalog-seasons-loading');return await ev(()=>document.querySelectorAll('#car-0 .car-skel').length===8&&!document.querySelector('.car.auto'))});
 await T('Пусто: «В этом сезоне пока нет онгоингов»',async()=>{await sel('demoCar','empty');await shot('243-catalog-seasons-empty');return await ev(()=>/В этом сезоне пока нет онгоингов/.test(document.querySelector('#car-0 .state').textContent))});
 await T('Ошибка → «Повторить»',async()=>{await sel('demoCar','error');await shot('244-catalog-seasons-error');const ok=await ev(()=>/Не удалось загрузить онгоинги/.test(document.querySelector('#car-0 .state').textContent));await (mob?p.locator('#car-0 [data-act=carRetry]').tap():p.locator('#car-0 [data-act=carRetry]').click());await p.waitForTimeout(1200);return ok&&await ev(()=>document.querySelectorAll('#car-0 .card').length>=8)});
 await T('Карточка тайтла → «Похожие»: «Связанные» и «Рекомендации AniList», с автопрокруткой',async()=>{await ev(()=>{S.titleId=2;S.titleTab='similar'});await go('title');await ev(()=>{document.querySelector('#car-rel').scrollIntoView({block:'start'});document.querySelector('#main').scrollTop-=70});await p.mouse.move(5,5);await p.waitForTimeout(200);await shot('245-title-related-recs');return (await ev(()=>[...document.querySelectorAll('.car h2')].map(h=>h.textContent).join('|')))==='Связанные|Рекомендации AniList'&&await ev(()=>document.querySelectorAll('.car.auto').length===2)&&await noHscroll()});
 await T('Карточка: пусто',async()=>{await sel('demoCar','empty');const ok=await ev(()=>/Связанных тайтлов нет/.test(document.querySelector('#car-rel .state').textContent)&&/Рекомендаций пока нет/.test(document.querySelector('#car-rec .state').textContent));await sel('demoCar','ok');await ev(()=>{S.titleTab='eps'});return ok});
 const bad=res.filter(r=>r[1]!=='OK');fails+=bad.length;console.log(th,vn,bad.length?bad:'все '+res.length+' OK',errs);await ctx.close();}
await b.close();process.exitCode=fails?1:0;})();
